import './ChipBar.css';
import type { Status } from '../../types';

interface ChipBarProps {
  statuses: Status[];
  selected: Set<Status>;
  onSelectionChange: (selected: Set<Status>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleChipClick(status: Status): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <div className="chip-bar" role="group" aria-label="Filter by status">
      {statuses.map((status) => (
        <button
          key={status}
          className="chip-bar__chip"
          aria-pressed={selected.has(status)}
          onClick={() => handleChipClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}
